// ============================================================================
// BuildPairsFromInventory (toStream-filtered)
// ----------------------------------------------------------------------------
// Purpose
//   Build a flat list of (nodeId, leafId) pairs from the persistent inventory
//   stored under global.genericNetList, but ONLY for points where `toStream` is true.
//   Each item also carries the siteKey, pointIndex, and a human label.
//
// Reads
//   global (persistent): genericNetList
//     └─ [siteKey].nodeff.Lindinspect_controller.points[*]
//
// Output (msg.payload)
//   Array of objects: { siteKey, pointIndex, nodeId, leafId, pointName }
//
// Notes
//   - `toStream` must be truthy per `isTrue()` below (true / "true" / 1).
//   - `leafId` primarily from '!leafId' (new model), legacy keys tolerated.
//   - `nodeId` from '!lindinspectid' (legacy keys tolerated).
//   - Points missing id(s) or not marked `toStream` are skipped.
// ============================================================================

const inv = global.get('genericNetList', 'persistent') || {};
const pairs = [];

function isTrue(v) {
  if (v === true) return true;
  if (v === 1) return true;
  if (typeof v === 'string' && v.trim().toLowerCase() === 'true') return true;
  return false;
}

for (const siteKey of Object.keys(inv)) {
  const site = inv[siteKey] || {};
  const ctrl = (site.nodeff && site.nodeff.Lindinspect_controller) || {};
  const points = Array.isArray(ctrl.points) ? ctrl.points : [];

  for (let i = 0; i < points.length; i++) {
    const p = points[i] || {};

    // Only include points explicitly flagged for streaming
    if (!isTrue(p.toStream)) continue;

    const leafId = p.leafId ?? p.leaf_id ?? p['@LEAF_ID'];
    const nodeId = p.lindinspectid ?? p['!LINDINSPECTID'] ?? p.nodeId;

    if (leafId == null || nodeId == null) continue; // skip incomplete

    pairs.push({
      siteKey,
      pointIndex: i,
      nodeId: String(nodeId),
      leafId: String(leafId),
      pointName: p.description || p.name || p['@name'] || undefined
    });
  }
}

if (pairs.length === 0) {
  node.status({ fill: 'red', shape: 'dot', text: 'no pairs (toStream=true) found' });
} else {
  node.status({ fill: 'green', shape: 'dot', text: `pairs: ${pairs.length}` });
}

msg.payload = pairs;
return msg;

// ============================================================================
// BuildRequest (/value) + HTTPS
// ----------------------------------------------------------------------------
// Purpose
//   Construct a GET request to Lindinspect for the leaf's current value:
//     GET {base}/api/v1/nodes/{nodeId}/leaves/{leafId}/value
//
// Reads
//   global (persistent): credentials { scheme, host, port, user, pass, baseUrl? }
//     - If baseUrl is present, it is normalized and ensured to end with /api/v1
//
// Input
//   msg.payload = { siteKey, pointIndex, nodeId, leafId, pointName }
//
// Output
//   Populates msg.method, msg.url, msg.headers, msg.timeout and carries
//   context fields (siteKey, pointIndex, pointName, nodeId, leafId) forward.
// ============================================================================

const creds = global.get('config','persistent') || {};

const scheme = (creds.scheme || 'http').toLowerCase();
const host   = creds.host || '127.0.0.1';
const port   = creds.port != null ? String(creds.port) : (scheme === 'https' ? '443' : '80');
const user   = creds.user || '';
const pass   = creds.pass || '';

// Prefer baseUrl but enforce /api/v1
let base = creds.baseUrl || `${scheme}://${host}:${port}`;
base = base.replace(/\/+$/,'');
if (!/\/api\/v1$/i.test(base)) base += '/api/v1';

const { nodeId, leafId } = msg.payload || {};
if (!nodeId || !leafId) return null; // drop incomplete

const url = `${base}/nodes/${encodeURIComponent(String(nodeId))}` +
            `/leaves/${encodeURIComponent(String(leafId))}/value`;

msg.method = 'GET';
msg.url = url;
msg.headers = msg.headers || {};
msg.headers.Accept = 'application/json';
msg.headers.Connection = 'close';

// Basic Auth
if (user && pass) {
  const token = Buffer.from(`${user}:${pass}`).toString('base64');
  msg.headers.Authorization = `Basic ${token}`;
} else {
  node.status({ fill:'red', shape:'ring', text:'missing credentials' });
}

msg.timeout = 15000; // ms

// Carry context forward
msg.siteKey    = msg.payload.siteKey;
msg.pointIndex = msg.payload.pointIndex;
msg.pointName  = msg.payload.pointName;
msg.nodeId     = String(nodeId);
msg.leafId     = String(leafId);

return msg;

// ============================================================================
// ShapeResult
// ----------------------------------------------------------------------------
// Purpose
//   Normalize the response from the value endpoint into a compact record and
//   carry forward contextual identifiers from previous steps.
//
// Input
//   msg.payload : response body (object or primitive)
//   msg.*       : context fields set in BuildRequest
//
// Output
//   msg.payload : {
//     siteKey, pointIndex, pointName, nodeId, leafId, value, at
//   }
// ============================================================================

const payload = msg.payload;

// Extract a value when the API wraps it as { value: ... }
const valueOut = (payload && Object.prototype.hasOwnProperty.call(payload, 'value'))
  ? payload.value
  : payload;

const rec = {
  siteKey: msg.siteKey,
  pointIndex: msg.pointIndex,
  pointName: msg.pointName,
  nodeId: msg.nodeId,
  leafId: msg.leafId,
  value: valueOut,
  at: new Date().toISOString()
};

msg.payload = rec;
return msg;

// ============================================================================
// Enrich → Telemetry Envelope
// ----------------------------------------------------------------------------
// Purpose
//   Convert raw readings to the target telemetry schema. Uses inventory to
//   resolve source labels and the precomputed HASH identifier for each point.
//
// Reads
//   global (persistent):
//     - credentials.JOB_UUID (optional; falls back to 'UNKNOWN_JOB_UUID')
//     - genericNetList (for point metadata)
//
// Input
//   msg.payload : Array<{
//     siteKey, pointIndex, value, nodeId, leafId, pointName, at
//   }>
//
// Output
//   msg.payload : Array<{
//     job_uuid, sourceLabel, dataType, time, value, hash, timestamp
//   }>
// ============================================================================

const creds = global.get('config','persistent') || {};
const JOB_UUID = creds.JOB_UUID || 'UNKNOWN_JOB_UUID';

const inv = global.get('genericNetList', 'persistent') || {};
const records = Array.isArray(msg.payload) ? msg.payload : [];

function coerceDataType(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return 'Double';
  if (typeof v === 'boolean') return 'Boolean';
  return 'String';
}

function buildFallbackLabel(p) {
  const sys  = p['system'];
  const comp = p['component'];
  const room = p['room'];
  const desc = p['description'];
  const left  = [sys, comp].filter(Boolean).join('-');
  const right = [room, desc].filter(Boolean).join('_');
  if (left && right) return `${left}-${right}`;
  return left || right || 'unknown_source';
}

const out = records.map(rec => {
  const site   = inv?.[rec.siteKey] || {};
  const points = site?.nodeff?.Lindinspect_controller?.points || [];
  const p      = points[rec.pointIndex] || {};

  // Value coercion (allow numeric strings → number)
  let rawValue = (rec && Object.prototype.hasOwnProperty.call(rec, 'value')) ? rec.value : undefined;
  if (typeof rawValue !== 'number') {
    const asNum = Number(rawValue);
    if (Number.isFinite(asNum)) rawValue = asNum;
  }

  const dataType    = coerceDataType(rawValue);
  const sourceLabel = p.orbiq_label || p.io_label || buildFallbackLabel(p);
  const hash        = p.HASH; // deterministic identifier in the current model

  const ts = new Date().toISOString();

  return {
    job_uuid: JOB_UUID,
    sourceLabel: String(sourceLabel || ''),
    dataType,
    time: ts,
    value: rawValue,
    hash,
    timestamp: ts
  };
});

// Keep only well-formed rows (require both hash and sourceLabel)
msg.payload = out.filter(o => o.hash && o.sourceLabel);

return msg;

// --- Normalize & Annotate (standalone) -------------------------------------
// Purpose: Ensure consistent payload shape and metadata before downstream steps.
// - Rounds numeric values to two decimals (if present)
// - Sets input origin on payload
// - Ensures ISO-8601 timestamps
// - Maintains simple per-input ingress counters in persistent flow context
// ------------------------------------------------------------------------------

const inputName = (typeof msg.input === "string" && msg.input) || "unknown";

msg.payload = msg.payload || {};

// 1) Normalize numeric value (accepts both number and numeric string)
if (msg.payload.value != null) {
  const n = Number(msg.payload.value);
  if (Number.isFinite(n)) msg.payload.value = Math.round(n * 100) / 100;
}

// 2) Attach input annotations on payload for downstream visibility
msg.payload.input = inputName;
if (msg.payload.measuredValueType == null) msg.payload.measuredValueType = inputName;

// 3) Simple ingress metric per input (persistent)
const inKey = `incoming_count:${inputName}`;
let inCount = flow.get(inKey, "persistent");
if (typeof inCount !== "number") inCount = 0;
flow.set(inKey, inCount + 1, "persistent");

return msg;

// --- Count Outgoing (standalone) -------------------------------------------
// Purpose: Maintain a simple per-input egress counter in persistent flow context.
// This is useful for quick health/throughput checks without external tooling.
// ------------------------------------------------------------------------------

const inputName = (typeof msg.input === "string" && msg.input) || "unknown";
const outKey = `outgoing_count:${inputName}`;
let outCount = flow.get(outKey, "persistent");
if (typeof outCount !== "number") outCount = 0;
flow.set(outKey, outCount + 1, "persistent");
return msg;

// --- Drop: older-than-last-accepted (array context, 2 outputs, hash-based) ---
// Output 1: PASS (message continues)
// Output 2: AUDIT (diagnostic events for drops)
//
// Purpose
//   • Guard against out-of-order or replayed telemetry by dropping any record
//     whose timestamp is older than the *latest accepted* timestamp per key.
//   • Use a compact, append-only array in persistent flow context to limit
//     memory; periodically compacts to keep size bounded.
//
// Identity key
//   • Uses msg.payload.hash (or msg.payload.HASH). If missing, a deterministic
//     fallback is built from (inputName, sourceLabel, job_uuid), assigned back
//     to msg.payload.hash, and used for tracking.
// ------------------------------------------------------------------------------

const STORE      = "persistent";
const SCOPE      = "per_hash";   // "per_hash" | "per_input" | "global"
const MAX_LEN    = 4000;         // upper bound before compaction
const COMPACT_TO = 1500;         // target unique keys after compaction

// --- Helpers -----------------------------------------------------------------
function parseToMs(t) {
  if (t == null) return NaN;
  if (t instanceof Date) return t.getTime();
  if (typeof t === "number") {
    if (t > 1e12) return t;         // already in ms
    if (t > 1e9)  return t * 1000;  // seconds → ms
    return t;                        // assume ms
  }
  if (typeof t === "string") {
    const n = Number(t);
    if (Number.isFinite(n)) return parseToMs(n);
    const p = Date.parse(t);
    return Number.isNaN(p) ? NaN : p;
  }
  return NaN;
}

const normIso = (ms) => new Date(ms).toISOString();

function resolveInputName(msg) {
  return (
    (typeof msg.input === "string" && msg.input) ||
    (typeof msg?.payload?.input === "string" && msg.payload.input) ||
    msg?.topic ||
    "unknown"
  );
}

function scopeId(msg) {
  const inputName = resolveInputName(msg);
  if (SCOPE === "per_hash")  return `perHash:${inputName}`;
  if (SCOPE === "per_input") return `perInput:${inputName}`;
  return "global";
}

function keyFromMsg(msg) {
  const inputName = resolveInputName(msg);

  // Prefer hash/HASH; otherwise deterministic fallback for visibility & stability.
  let hash = (msg?.payload?.hash ?? msg?.payload?.HASH);
  if (!hash) {
    const sl = String(msg?.payload?.sourceLabel ?? "unknown");
    const ju = String(msg?.payload?.job_uuid    ?? "na");
    hash = `${inputName}:${sl}:${ju}`;
    if (msg?.payload) msg.payload.hash = hash;
  }
  return { inputName, hash: String(hash) };
}

function getArr(sid) {
  const k = `latestSeenArr:${sid}`;
  let arr = flow.get(k, STORE);
  if (!Array.isArray(arr)) arr = [];
  return { k, arr };
}

function latestForKey(arr, key) {
  for (let i = arr.length - 1; i >= 0; i--) {
    const row = arr[i];
    if (row && row[0] === key) return row[1];
  }
  return -Infinity;
}

function pushAndMaybeCompact(k, arr, key, ts) {
  arr.push([key, ts]);
  if (arr.length > MAX_LEN) {
    const seen = new Set();
    const compact = [];
    for (let i = arr.length - 1; i >= 0 && compact.length < COMPACT_TO; i--) {
      const row = arr[i]; if (!row) continue;
      const u = row[0];
      if (!seen.has(u)) { compact.push(row); seen.add(u); }
    }
    compact.reverse();
    arr = compact;
  }
  flow.set(k, arr, STORE);
}

// --- Main --------------------------------------------------------------------
msg.payload = msg.payload || {};

let incomingMs = parseToMs(msg.payload.time ?? msg.payload.timestamp ?? Date.now());
if (!Number.isFinite(incomingMs)) {
  node.status({ text: "drop (invalid time)" });
  let c = flow.get("dropped_invalid_time", STORE); if (typeof c !== "number") c = 0; flow.set("dropped_invalid_time", c+1, STORE);
  const audit = { payload: { outcome: "drop", reason: "INVALID_TIME", input: resolveInputName(msg) } };
  return [null, audit];
}
const iso = normIso(incomingMs);
msg.payload.time = iso;
msg.payload.timestamp = iso;

const { inputName, hash } = keyFromMsg(msg);
const sid = scopeId(msg);
const { k, arr } = getArr(sid);

// Choose lookup key by scope
const lookupKey =
  (SCOPE === "per_hash")  ? hash :
  (SCOPE === "per_input") ? "__input__" :
                            "__global__";

const lastMs = latestForKey(arr, lookupKey);

if (incomingMs < lastMs) {
  const lastIso = normIso(lastMs);
  const dk = `dropped_older_than_youngest:${inputName}`;
  let c = flow.get(dk, STORE); if (typeof c !== "number") c = 0; flow.set(dk, c+1, STORE);
  node.status({ text: `drop < ${lastIso}` });
  const audit = {
    payload: {
      outcome: "drop",
      reason: "OLDER_THAN_YOUNGEST",
      incomingIso: iso,
      lastAcceptedIso: lastIso,
      input: inputName,
      scope: SCOPE,
      key: lookupKey,
      hash
    }
  };
  return [null, audit];
}

// Accept and update latest time
pushAndMaybeCompact(k, arr, lookupKey, incomingMs);

let a = flow.get(`accepted_count:${inputName}`, STORE); if (typeof a !== "number") a = 0; flow.set(`accepted_count:${inputName}`, a+1, STORE);
node.status({ text: "ok (new or equal)" });
return [msg, null];

// --- Filter: change/keepalive (standalone, hash-based, no whitelist) ---------
// Purpose
//   • Emit a message when the value has changed, OR when a keepalive interval
//     has elapsed since the last emission.
//   • Maintain per-input value state in persistent flow context (survives restarts).
// Behavior
//   • Uses msg.payload.hash (or msg.payload.HASH) as the identity key.
//   • If no hash is present, builds a deterministic fallback from
//     (inputName, sourceLabel, job_uuid), assigns it to msg.payload.hash, and
//     uses that for state tracking.
// ------------------------------------------------------------------------------

const STORE   = "persistent";
const TIMEOUT = 60 * 60 * 1000; // keepalive interval (ms) — adjust as needed

// Resolve a stable "input name" namespace for state separation
const inputName =
  (typeof msg.input === "string" && msg.input) ||
  (typeof msg?.payload?.input === "string" && msg.payload.input) ||
  msg?.topic ||
  "unknown";

// Load (or initialize) the per-input store
let store = flow.get("valueStore", STORE) || {};
if (!store[inputName]) store[inputName] = {};
const ns = store[inputName];

// --- Resolve hash identity ----------------------------------------------------
let hash = (msg?.payload?.hash ?? msg?.payload?.HASH);
if (!hash) {
  const sl = String(msg?.payload?.sourceLabel ?? "unknown");
  const ju = String(msg?.payload?.job_uuid    ?? "na");
  hash = `${inputName}:${sl}:${ju}`;
  if (msg?.payload) msg.payload.hash = hash;
}

// ---- Change / keepalive policy ----------------------------------------------
const newValue = msg?.payload?.value;
const now = Date.now();

// Minimal state per hash
let entry = ns[hash] || {
  lastValue: undefined,
  lastSent:  0
};

let shouldSend = false;

// Emit if value changed...
if (newValue !== entry.lastValue) {
  entry.lastValue = newValue;
  entry.lastSent  = now;
  shouldSend = true;

// ...or if keepalive interval has elapsed
} else if ((now - entry.lastSent) >= TIMEOUT) {
  entry.lastSent = now;
  shouldSend = true;
}

// Persist updated state
ns[hash] = entry;
store[inputName] = ns;
flow.set("valueStore", store, STORE);

// Optional status for quick visual feedback in the editor
node.status({
  fill: shouldSend ? "green" : "grey",
  shape: "dot",
  text: shouldSend ? "emit (change/keepalive)" : "suppressed (no change)"
});

return shouldSend ? msg : null;

// Poll Scheduler (styr via global.config.pollingInterval)
// - Läser global.get('config','persistent').pollingInterval (ms eller s)
// - Start/stop/reload via msg.control: "start" | "stop" | "reload"
// - Skickar ett tick: { topic: "poll", payload: Date.now() } varje intervall

const STORE = "persistent";
const cfg = global.get("config", STORE) || {};
let ms = Number(cfg.pollingInterval);

// Tillåt att man råkar ange sekunder
if (Number.isFinite(ms) && ms > 0 && ms < 10_000) ms = ms * 1000;
// Fallback
if (!Number.isFinite(ms) || ms <= 0) ms = 60_000; // 60s default

let timer = context.get("pollTimer");

function startTimer() {
  if (timer) clearInterval(timer);
  timer = setInterval(() => {
    node.send({ topic: "poll", payload: Date.now() });
  }, ms);
  context.set("pollTimer", timer);
  node.status({ fill: "green", shape: "dot", text: `polling ${ms} ms` });
}

function stopTimer() {
  if (timer) { clearInterval(timer); timer = null; }
  context.set("pollTimer", null);
  node.status({ fill: "grey", shape: "ring", text: "stopped" });
}

const cmd = (msg.control || "").toLowerCase();
if (cmd === "stop")  { stopTimer(); return null; }
if (cmd === "start") { startTimer(); return null; }
if (cmd === "reload"){ startTimer(); return null; }

// Autostarta om inget kommandot skickas
if (!timer) startTimer();

// Vi producerar själv tickar; inkommande meddelanden släpps igenom om man vill trigga manuellt.
return null;
